{
  "root_causes": [
    {
      "service": "ts-user-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, count(*) n, round(avg(duration)/1e6,1) reg_avg_ms, round(max(duration)/1e6,1) reg_max_ms FROM abnormal_traces WHERE service_name='ts-user-service' AND span_name='UserController.registerUser' UNION ALL SELECT 'norm', count(*), round(avg(duration)/1e6,1), round(max(duration)/1e6,1) FROM normal_traces WHERE service_name='ts-user-service' AND span_name='UserController.registerUser'",
          "claim": "registerUser self-time rose: avg 83.5 ms normal to 110.3 ms abnormal, max 85.5 to 296.5 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT s.service_name, s.span_name, s.attr_span_kind k, round(s.duration/1e6,1) ms FROM abnormal_traces s WHERE s.trace_id IN (SELECT DISTINCT trace_id FROM abnormal_traces WHERE service_name='ts-admin-user-service' AND span_name LIKE 'POST%') AND s.service_name IN ('ts-user-service') ORDER BY s.time",
          "claim": "In slow traces, ts-user-service DB spans take about 1 ms, while registerUser takes about 290 ms with no traced child for the gap."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, count(*) n FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name='POST /api/v1/adminuserservice/users' GROUP BY 1",
          "claim": "User-facing POST /api/v1/adminuserservice/users p95 reaches about 1753 ms in the incident window, versus about 92 ms normal."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-user-service",
      "to": "ts-admin-user-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH e_a AS (SELECT c.service_name cs, p.service_name ps, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) p95 FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.service_name<>p.service_name GROUP BY ALL), e_n AS (SELECT c.service_name cs, p.service_name ps, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) p95 FROM normal_traces c JOIN normal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.service_name<>p.service_name GROUP BY ALL) SELECT coalesce(a.cs,n.cs) child, coalesce(a.ps,n.ps) parent, n.p95 normal_p95, a.p95 abnormal_p95 FROM e_a a FULL JOIN e_n n USING (cs,ps) WHERE coalesce(a.cs,n.cs)='ts-user-service' AND coalesce(a.ps,n.ps)='ts-admin-user-service'",
          "claim": "Child ts-user-service spans called by ts-admin-user-service slowed: p95 about 86 ms normal to about 254 ms abnormal."
        }
      ]
    },
    {
      "from": "ts-admin-user-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH e_a AS (SELECT c.service_name cs, p.service_name ps, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) p95 FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.service_name<>p.service_name GROUP BY ALL), e_n AS (SELECT c.service_name cs, p.service_name ps, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) p95 FROM normal_traces c JOIN normal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.service_name<>p.service_name GROUP BY ALL) SELECT coalesce(a.cs,n.cs) child, coalesce(a.ps,n.ps) parent, n.p95 normal_p95, a.p95 abnormal_p95 FROM e_a a FULL JOIN e_n n USING (cs,ps) WHERE coalesce(a.cs,n.cs)='ts-admin-user-service' AND coalesce(a.ps,n.ps)='ts-ui-dashboard'",
          "claim": "ts-admin-user-service spans under ts-ui-dashboard slowed: p95 about 91 ms normal to about 187 ms abnormal."
        }
      ]
    },
    {
      "from": "ts-ui-dashboard",
      "to": "loadgenerator",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, count(*) n FROM abnormal_traces WHERE service_name='loadgenerator' AND attr_span_kind='Client' AND span_name LIKE '%adminuserservice/users%' GROUP BY 1",
          "claim": "The user-side client's POST to the admin-user endpoint through ts-ui-dashboard shows the same slow tail as the dashboard server span."
        }
      ]
    }
  ]
}
